import React from 'react';

export default function StudentSchedule() {
  const schedule = [
    {
      id: 1,
      courseName: "React Basics",
      day: "Monday",
      time: "10:00 AM - 11:30 AM",
      room: "Lab 101",
      instructor: "John Doe"
    },
    {
      id: 2,
      courseName: "JavaScript Advanced",
      day: "Tuesday",
      time: "2:00 PM - 3:30 PM",
      room: "Lab 202",
      instructor: "Jane Smith"
    },
    {
      id: 3,
      courseName: "React Basics",
      day: "Wednesday",
      time: "10:00 AM - 11:30 AM",
      room: "Lab 101",
      instructor: "John Doe"
    },
    {
      id: 4,
      courseName: "Web Design",
      day: "Thursday",
      time: "1:00 PM - 2:30 PM",
      room: "Lab 303",
      instructor: "Mike Johnson"
    },
    {
      id: 5,
      courseName: "JavaScript Advanced",
      day: "Friday",
      time: "2:00 PM - 3:30 PM",
      room: "Lab 202",
      instructor: "Jane Smith"
    }
  ];

  return (
    <div style={{ padding: '20px' }}>
      <h2>My Schedule</h2>
      
      {schedule.length === 0 ? (
        <p>No scheduled classes</p>
      ) : (
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '15px'
        }}>
          {schedule.map((session) => (
            <div key={session.id} style={{
              background: '#f5f5f5',
              border: '2px solid #007bff',
              padding: '15px',
              borderRadius: '10px'
            }}>
              <h3 style={{ marginTop: 0 }}>{session.courseName}</h3>
              <p><strong>Day:</strong> {session.day}</p>
              <p><strong>Time:</strong> {session.time}</p>
              <p><strong>Room:</strong> {session.room}</p>
              <p><strong>Instructor:</strong> {session.instructor}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
